// ─── File: AuthCodeFlowDemo.java ───
package com.bank.authcode;

import java.util.*;
import java.util.logging.*;

public class AuthCodeFlowDemo {
    private static final Logger log = Logger.getLogger(AuthCodeFlowDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthorizationServer authServer = new AuthorizationServer("partner-site", "super-secret");
        ClientBackend backend = new ClientBackend("partner-site", "super-secret", authServer);

        // Front channel: user consents, server returns a CODE to the browser (not a token).
        String code = authServer.issueCode("rajesh", "https://partner.example/callback");
        log.info(() -> "Front-channel redirect carried only a CODE: " + code);

        // Back channel: backend exchanges code + secret for a token (server-to-server).
        String token = backend.exchangeCodeForToken(code, "https://partner.example/callback");
        log.info(() -> "Back-channel exchange returned access token: " + token);

        // Attacker steals the code but has NO client secret -> exchange fails.
        ClientBackend attacker = new ClientBackend("partner-site", "wrong-secret", authServer);
        try {
            attacker.exchangeCodeForToken(code, "https://partner.example/callback");
        } catch (CodeExchangeException e) {
            log.severe("Attacker exchange failed: " + e.getMessage());
        }

        // Reuse of an already-used code -> rejected.
        try {
            backend.exchangeCodeForToken(code, "https://partner.example/callback");
        } catch (CodeExchangeException e) {
            log.warning("Code reuse rejected: " + e.getMessage());
        }
    }
}

// ─── Would be in CodeExchangeException.java ───
class CodeExchangeException extends RuntimeException {
    CodeExchangeException(String m) { super(m); }
}

// ─── Would be in AuthorizationServer.java ───
class AuthorizationServer {
    private final String clientId; private final String clientSecret;
    private final Map<String, String[]> codes = new HashMap<>(); // code -> {user, redirect, used}
    AuthorizationServer(String clientId, String clientSecret) {
        this.clientId = clientId; this.clientSecret = clientSecret;
    }

    String issueCode(String username, String redirectUri) {
        String code = "code-" + UUID.randomUUID();
        codes.put(code, new String[]{username, redirectUri, "false"});
        return code; // returned via browser redirect (front channel)
    }

    // Back-channel token endpoint: requires the client secret.
    String exchangeToken(String code, String redirectUri, String presentedSecret) {
        String[] rec = codes.get(code);
        if (rec == null) throw new CodeExchangeException("invalid code");
        if ("true".equals(rec[2])) throw new CodeExchangeException("code already used");
        if (!redirectUri.equals(rec[1])) throw new CodeExchangeException("redirect_uri mismatch");
        if (!clientSecret.equals(presentedSecret)) throw new CodeExchangeException("bad client secret");
        rec[2] = "true"; // single-use
        return "access-token-for-" + rec[0];
    }
}

// ─── Would be in ClientBackend.java ───
class ClientBackend {
    private final String clientId; private final String clientSecret;
    private final AuthorizationServer authServer;
    ClientBackend(String clientId, String clientSecret, AuthorizationServer authServer) {
        this.clientId = clientId; this.clientSecret = clientSecret; this.authServer = authServer;
    }
    // This runs on the SERVER, never in the browser.
    String exchangeCodeForToken(String code, String redirectUri) {
        return authServer.exchangeToken(code, redirectUri, clientSecret);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
